-- Dá ao time de marketing acesso de leitura só ao catálogo curated
GRANT USE CATALOG ON CATALOG curated TO `marketing`;
GRANT USE SCHEMA ON SCHEMA curated.vendas TO `marketing`;
GRANT SELECT ON SCHEMA curated.vendas TO `marketing`;

-- Garante que marketing NÃO tem nenhum acesso ao catálogo raw
REVOKE ALL PRIVILEGES ON CATALOG raw FROM `marketing`;

